#include "crawler/api/controllers/ResourceTransferOpenApi.h"
#include <nlohmann/json.hpp>

namespace orchestrator::modules::crawler::api::controllers {
void appendResourceStatusOpenApi(nlohmann::json &document)
{
    document["paths"]["/api/v2/migu/resources/status"] = nlohmann::json::parse(R"statusjson({"post":{"tags":["migu"],"summary":"Read local and both cloud facts for one resource page","description":"Read only in maintenance and legacy mode. At most 200 distinct complete file identities. All three targets are returned; destinations controls aggregation only and defaults to all three even when a target is disabled. Missing resources remain found=false in input order. A missing cloud receipt is null. Historical skip and operator attestation do not imply current. Current matches persisted content and target versions; it does not prove the file is online. No URL, object path, task creation or content I/O. Current strict SHA256 policy can only narrow cloud current.","requestBody":{"required":true,"content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2ResourceStatusQuery"}}}},"responses":{"200":{"description":"Persisted facts only; no online probe or transfer.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/V2ResourceStatusBatch"}}}},"400":{"description":"Invalid or duplicate identity; no work accepted.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"500":{"description":"Read failed.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}},"503":{"description":"Incompatible schema or unavailable query adapter.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}}}}})statusjson");
    document["components"]["schemas"]["V2ResourceStatusQuery"] = nlohmann::json::parse(R"statusjson({"type":"object","additionalProperties":false,"required":["resources"],"properties":{"resources":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["owner_type","resource_id"],"properties":{"owner_type":{"type":"string","enum":["song","singer","album","song_artifact"]},"resource_id":{"type":"integer","minimum":1}}},"minItems":1,"maxItems":200},"destinations":{"type":"array","items":{"type":"string","enum":["local","baidu","gdrive"]},"maxItems":3,"uniqueItems":true}}})statusjson");
    document["components"]["schemas"]["V2LocalReceipt"] = nlohmann::json::parse(R"statusjson({"type":"object","additionalProperties":false,"required":["status","content_generation","target_revision","current_content_generation","current_target_revision","size_bytes","checksum","path_resolved","current","transfer_skipped"],"properties":{"status":{"type":"integer","minimum":0},"content_generation":{"type":"integer","minimum":0},"target_revision":{"type":"integer","minimum":0},"current_content_generation":{"type":"integer","minimum":0},"current_target_revision":{"type":"integer","minimum":0},"size_bytes":{"type":"integer","minimum":0},"checksum":{"type":"string"},"path_resolved":{"type":"boolean"},"current":{"type":"boolean"},"transfer_skipped":{"type":"boolean"}}})statusjson");
    document["components"]["schemas"]["V2ResourceStatus"] = nlohmann::json::parse(R"statusjson({"type":"object","additionalProperties":false,"required":["owner_type","resource_id","found","local","cloud_receipts","all_requested_targets_current"],"properties":{"owner_type":{"type":"string","enum":["song","singer","album","song_artifact"]},"resource_id":{"type":"integer","minimum":1},"found":{"type":"boolean"},"local":{"$ref":"#/components/schemas/V2LocalReceipt"},"cloud_receipts":{"type":"object","additionalProperties":false,"required":["baidu","gdrive"],"properties":{"baidu":{"type":"object","nullable":true,"allOf":[{"$ref":"#/components/schemas/V2CloudReceipt"}]},"gdrive":{"type":"object","nullable":true,"allOf":[{"$ref":"#/components/schemas/V2CloudReceipt"}]}}},"all_requested_targets_current":{"type":"boolean"}}})statusjson");
    document["components"]["schemas"]["V2ResourceStatusBatch"] = nlohmann::json::parse(R"statusjson({"type":"object","additionalProperties":false,"required":["requested_targets","items"],"properties":{"requested_targets":{"type":"array","items":{"type":"string","enum":["local","baidu","gdrive"]},"maxItems":3,"uniqueItems":true},"items":{"type":"array","maxItems":200,"items":{"$ref":"#/components/schemas/V2ResourceStatus"}}}})statusjson");
}
} // namespace orchestrator::modules::crawler::api::controllers
